INSERT INTO "permissions" ("key", "description") VALUES ('hr.credential.read', 'View employee kiosk credentials (biometric templates, cards)'), ('hr.credential.enroll', 'Start kiosk enrollment sessions for biometrics and cards'), ('hr.credential.revoke', 'Revoke employee biometric templates and cards') ON CONFLICT ("key") DO NOTHING;--> statement-breakpoint
INSERT INTO "role_permissions" ("role_id", "permission_key") SELECT r."id", p."key" FROM "roles" r CROSS JOIN (VALUES ('hr.credential.read'::"permission_list"), ('hr.credential.enroll'::"permission_list"), ('hr.credential.revoke'::"permission_list")) AS p("key") WHERE r."key" IN ('OWNER', 'ADMIN', 'HR_MANAGER') ON CONFLICT DO NOTHING;--> statement-breakpoint
